// === Tab: mySketch ===
//for the #wccChallenge on the topic of "Azulejos" ---> code by Aaron Reuland
//Very excited about the topic being chosen. 
//Decided to give myself the challenge of making something with shaders
//which I'm still learning.
//I've made tiling patterns related to azulejos before 
//like this Genuary sketch: https://openprocessing.org/sketch/1792369 .
//So, I tried to do someting a little different here.
//Ended up cheating out the last overlaying pattern in p5, as it
//was sooo much easier than trying to make it happen in the shader.

let theShader;
let d

function preload(){
	theShader = createShader(vert, frag)
}

function setup() {
	createCanvas(windowWidth,windowHeight, WEBGL);
	d= createGraphics(width, height)
	noStroke()
	pixelDensity(1)
	d.noFill()

	let tileSize= height/7.0;
	for(let x=-tileSize; x<=width+tileSize; x+=tileSize){
		for(let y=-tileSize; y<=height+tileSize; y+=tileSize){
			d.stroke(0, 100)
			d.rect(x, y, tileSize);
			d.strokeWeight(1);
			d.stroke('#1362AF')
			d.ellipse(x+tileSize/2, y+tileSize/2, tileSize*2);
		}
	}

}

function draw() {
	shader(theShader)
	background(255);
	theShader.setUniform('u_resolution',[windowWidth,windowHeight])
	theShader.setUniform('u_time',millis()/600)
	theShader.setUniform('u_mouse',[(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))/width,(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))/height])
	rect(-width/2, -height/2,width,height)
	image(d, -width/2, -height/2)
}

// === Tab: frag ===
//My code really starts around line 160-- before that are  various standard defintion and functions

const frag = `
	#ifdef GL_ES
precision highp float;
#endif

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;

#define PI 3.14159265359

// Some useful functions
vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec2 mod289(vec2 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
vec3 permute(vec3 x) { return mod289(((x*34.0)+1.0)*x); }

//
// Description : GLSL 2D simplex noise function
//      Author : Ian McEwan, Ashima Arts
//  Maintainer : ijm
//     Lastmod : 20110822 (ijm)
//     License :
//  Copyright (C) 2011 Ashima Arts. All rights reserved.
//  Distributed under the MIT License. See LICENSE file.
//  https://github.com/ashima/webgl-noise
//

float snoise(vec2 v) {

    // Precompute values for skewed triangular grid
    const vec4 C = vec4(0.211324865405187,
                        // (3.0-sqrt(3.0))/6.0
                        0.366025403784439,
                        // 0.5*(sqrt(3.0)-1.0)
                        -0.577350269189626,
                        // -1.0 + 2.0 * C.x
                        0.024390243902439);
                        // 1.0 / 41.0

    // First corner (x0)
    vec2 i  = floor(v + dot(v, C.yy));
    vec2 x0 = v - i + dot(i, C.xx);

    // Other two corners (x1, x2)
    vec2 i1 = vec2(0.0);
    i1 = (x0.x > x0.y)? vec2(1.0, 0.0):vec2(0.0, 1.0);
    vec2 x1 = x0.xy + C.xx - i1;
    vec2 x2 = x0.xy + C.zz;

    // Do some permutations to avoid
    // truncation effects in permutation
    i = mod289(i);
    vec3 p = permute(
            permute( i.y + vec3(0.0, i1.y, 1.0))
                + i.x + vec3(0.0, i1.x, 1.0 ));

    vec3 m = max(0.5 - vec3(
                        dot(x0,x0),
                        dot(x1,x1),
                        dot(x2,x2)
                        ), 0.0);

    m = m*m ;
    m = m*m ;

    // Gradients:
    //  41 pts uniformly over a line, mapped onto a diamond
    //  The ring size 17*17 = 289 is close to a multiple
    //      of 41 (41*7 = 287)

    vec3 x = 2.0 * fract(p * C.www) - 1.0;
    vec3 h = abs(x) - 0.5;
    vec3 ox = floor(x + 0.5);
    vec3 a0 = x - ox;

    // Normalise gradients implicitly by scaling m
    // Approximation of: m *= inversesqrt(a0*a0 + h*h);
    m *= 1.79284291400159 - 0.85373472095314 * (a0*a0+h*h);

    // Compute final noise value at P
    vec3 g = vec3(0.0);
    g.x  = a0.x  * x0.x  + h.x  * x0.y;
    g.yz = a0.yz * vec2(x1.x,x2.x) + h.yz * vec2(x1.y,x2.y);
    return 130.0 * dot(m, g);
}

	float rand(vec2 c){
		return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
	}

vec3 random3(vec3 c) {
    float j = 4096.0*sin(dot(c,vec3(17.0, 59.4, 15.0)));
    vec3 r;
    r.z = fract(512.0*j);
    j *= .125;
    r.x = fract(512.0*j);
    j *= .125;
    r.y = fract(512.0*j);
    return r-0.5;
}	


const float F3 =  0.3333333;
const float G3 =  0.1666667;
float s3noise(vec3 p) {

    vec3 s = floor(p + dot(p, vec3(F3)));
    vec3 x = p - s + dot(s, vec3(G3));

    vec3 e = step(vec3(0.0), x - x.yzx);
    vec3 i1 = e*(1.0 - e.zxy);
    vec3 i2 = 1.0 - e.zxy*(1.0 - e);

    vec3 x1 = x - i1 + G3;
    vec3 x2 = x - i2 + 2.0*G3;
    vec3 x3 = x - 1.0 + 3.0*G3;

    vec4 w, d;

    w.x = dot(x, x);
    w.y = dot(x1, x1);
    w.z = dot(x2, x2);
    w.w = dot(x3, x3);

    w = max(0.6 - w, 0.0);

    d.x = dot(random3(s), x);
    d.y = dot(random3(s + i1), x1);
    d.z = dot(random3(s + i2), x2);
    d.w = dot(random3(s + 1.0), x3);

    w *= w;
    w *= w;
    d *= w;

    return dot(d, vec4(52.0));
}

float sdCircle( vec2 p, float r )
{
    return length(p) - r;
}

float sdTriangle( in vec2 p, in vec2 p0, in vec2 p1, in vec2 p2 )
{
    vec2 e0 = p1-p0, e1 = p2-p1, e2 = p0-p2;
    vec2 v0 = p -p0, v1 = p -p1, v2 = p -p2;
    vec2 pq0 = v0 - e0*clamp( dot(v0,e0)/dot(e0,e0), 0.0, 1.0 );
    vec2 pq1 = v1 - e1*clamp( dot(v1,e1)/dot(e1,e1), 0.0, 1.0 );
    vec2 pq2 = v2 - e2*clamp( dot(v2,e2)/dot(e2,e2), 0.0, 1.0 );
    float s = sign( e0.x*e2.y - e0.y*e2.x );
    vec2 d = min(min(vec2(dot(pq0,pq0), s*(v0.x*e0.y-v0.y*e0.x)),
                     vec2(dot(pq1,pq1), s*(v1.x*e1.y-v1.y*e1.x))),
                     vec2(dot(pq2,pq2), s*(v2.x*e2.y-v2.y*e2.x)));
    return -sqrt(d.x)*sign(d.y);
}

float nsdVesica(vec2 p, float r, float d, vec2 bst)
{
    p = abs(p+s3noise(vec3(p+bst, u_time/17.)*5.)/10.);
    float b = sqrt(r*r-d*d);
    return ((p.y-b)*d>p.x*b) ? length(p-vec2(0.0,b))
                             : length(p-vec2(-d,0.0))-r;
}


void main() {
    vec2 st = gl_FragCoord.xy/u_resolution.xy;
    st.x *= u_resolution.x/u_resolution.y;

	  st *= 7.0;  
		vec2 bst= st;
    st = fract(st);
    vec2 p = st;

  vec3 bgColor= vec3(0.7215, 0.7725, 0.9392)- snoise(vec2(bst.x/10.+u_time/13., bst.y/5.+u_time/12.))/8.+rand(bst*2.)/7.;
  vec3 circ= vec3(smoothstep(0.02, 0.04, sdCircle(p-0.5, 0.47)));
	 vec3 circc = vec3(0.976, 0.969, 0.941)-snoise(vec2(bst.x/10.+u_time/13., bst.y/5.+u_time/12.))/8.+rand(bst*2.)/7.;
	vec3 bg= mix(circc, bgColor, circ);
  vec3 cs=  vec3(smoothstep(0.0, 0.2, nsdVesica(p - vec2(0.5, 0.5), 0.3, 0.15, bst)));
  vec3 cColor= vec3(0.12156, 0.2392, 0.6235);

	vec3 result= mix(cColor, bg, cs);

	vec3 cornerC= vec3(0.0745, 0.3843, 0.6862);
	vec3 llc= vec3(smoothstep(0.025,0.07, sdTriangle(p, vec2(0., 0.), vec2(0., 0.1), vec2(0.1, .0))));
	vec3 ulc= vec3(smoothstep(0.025,0.07, sdTriangle(p, vec2(0., 1.), vec2(0., 0.9), vec2(0.1, 1.))));
	vec3 urc= vec3(smoothstep(0.025,0.07, sdTriangle(p, vec2(1., 1.), vec2(0.9, 1.), vec2(1., 0.9))));
  vec3 lrc= vec3(smoothstep(0.025,0.07, sdTriangle(p, vec2(1., 0.), vec2(0.9, 0.), vec2(1., 0.1))));

	vec3 corners= llc*ulc*urc*lrc;
	vec3 c=mix(cornerC, corners, corners);

	vec3 color=mix(c, result, c);
	vec3 iv= vec3(smoothstep(-0.2, 0.1, nsdVesica(p - vec2(0.5, 0.5), 0.2, 0.15, bst)));
	vec3 fcolor=mix(bgColor, color ,iv);

  gl_FragColor = vec4(fcolor, 1.);
}
`





// === Tab: vert ===
//ref 3d shader from https://www.openprocessing.org/sketch/881537

const vert = `
	precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
		varying vec4 var_centerGlPosition;//原点

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;
		uniform float u_time;


    void main() {
      vec3 pos = aPosition;
			vec4 posOut = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
      gl_Position = posOut;

      // set out value
      var_vertPos      = pos;
      var_vertNormal   =  aNormal;
      var_vertTexCoord = aTexCoord;
			var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * vec4(0., 0., 0.,1.0);
    }
`;

